{
  "timeZone": "Europe/Brussels",
  "dependencies": {
  },
  "webapp": {
    "access": "ANYONE_ANONYMOUS",
    "executeAs": "USER_DEPLOYING"
  },
  "exceptionLogging": "STACKDRIVER",
  "runtimeVersion": "V8"
}

// GAS entry points: doGet/doPost. De front-end praat via het standaard `google.script.run`-
// mechanisme met de functies hieronder — dat vereist dat de pagina via HtmlService.evaluate()
// geserveerd wordt (niet via ContentService: die geeft op /exec bij nader inzien altijd
// Content-Type text/plain terug, ongeacht setMimeType(HTML), en rendert dus niet als pagina).
//
// Toegang: geen account/login. Elke gebruiker heeft een eigen, niet-geraden gebruikers-ID (een
// UUID, gegenereerd in de browser bij het eerste bezoek en bewaard in de URL + localStorage).
// Wie die ID kent, kan bij dat profiel — vergelijkbaar met een deel-link. Zie README.md
// "Aannames" voor de afweging.

// Handmatig ophogen bij elke betekenisvolle wijziging/deploy — zichtbaar onderin de app, zodat
// eenvoudig te controleren is of een nieuwe versie daadwerkelijk live staat (i.p.v. een gecachete
// oudere versie in de browser).
var KITEWEER_VERSIE = 'v16 (30 aug 2026)';

function doGet(e) {
  var template = HtmlService.createTemplateFromFile('index');
  // De pagina draait zelf in een geneste iframe met een eigen, instabiele interne URL — voor de
  // deel-/bookmarklink die de gebruiker te zien krijgt hebben we de echte, publieke /exec-URL
  // nodig, die alleen de server kent (ScriptApp.getService().getUrl()). Om dezelfde reden lezen
  // we een meegegeven ?id=... hier server-side uit `e.parameter` i.p.v. te vertrouwen op
  // location.search in de client (die weerspiegelt de interne iframe-URL, niet de bezochte URL).
  template.webappUrl = ScriptApp.getService().getUrl();
  template.gebruikerIdUitUrl = (e && e.parameter && e.parameter.id) || null;
  template.versie = KITEWEER_VERSIE;
  return template
    .evaluate()
    .setTitle('Kite Weer App')
    .addMetaTag('viewport', 'width=device-width, initial-scale=1');
}

/**
 * Enige binnenkomende kanaal voor de Telegram-bot-webhook (zie TelegramBot.gs) — niet gebruikt
 * door de webapp zelf (die praat via google.script.run, niet via doPost).
 */
function doPost(e) {
  try {
    var update = JSON.parse((e && e.postData && e.postData.contents) || '{}');
    if (update.message) verwerkTelegramBericht_(update.message);
  } catch (err) {
    // Onverwachte/ongeldige payload: negeren, geen foutrespons nodig richting Telegram.
  }
  return ContentService.createTextOutput(JSON.stringify({ ok: true })).setMimeType(
    ContentService.MimeType.JSON
  );
}

/** Voegt een HTML-partial in vanuit een <?!= include('naam'); ?> template-tag. */
function include(bestandsnaam) {
  return HtmlService.createHtmlOutputFromFile(bestandsnaam).getContent();
}

/** Simpele sanity-check op het gebruikers-ID (moet een niet-lege string zijn, verder geen eisen). */
function metGebruiker_(gebruikerId, fn) {
  if (!gebruikerId || typeof gebruikerId !== 'string') {
    return { fout: 'Ongeldig of ontbrekend gebruikers-ID' };
  }
  return fn(gebruikerId.trim().slice(0, 100));
}

function getProfiel(gebruikerId) {
  return metGebruiker_(gebruikerId, function (id) {
    return { profiel: laadProfiel_(id) };
  });
}

function saveProfiel(gebruikerId, ruwProfiel) {
  return metGebruiker_(gebruikerId, function (id) {
    var resultaat = slaProfielOp_(id, ruwProfiel);
    return { profiel: resultaat.profiel, fouten: resultaat.fouten };
  });
}

function voegFavorieteLocatieToeServer(gebruikerId, ruweLocatie) {
  return metGebruiker_(gebruikerId, function (id) {
    var profiel = laadProfiel_(id);
    var resultaat = voegFavorieteLocatieToe(profiel, ruweLocatie);
    slaProfielOp_(id, resultaat.profiel);
    return resultaat;
  });
}

function verwijderFavorieteLocatieServer(gebruikerId, locatieId) {
  return metGebruiker_(gebruikerId, function (id) {
    var profiel = laadProfiel_(id);
    var nieuw = verwijderFavorieteLocatie(profiel, locatieId);
    slaProfielOp_(id, nieuw);
    return { profiel: nieuw };
  });
}

/**
 * Haalt het 3-daagse weeroordeel op voor één locatie, met de drempelwaarden en databronnen-
 * instellingen van de gebruiker gecombineerd met de windrichting-configuratie van die specifieke
 * favoriete locatie.
 * @param {string} gebruikerId
 * @param {{lat: number, lon: number, windrichting?: Object}} locatie
 */
function getWeerOordeel(gebruikerId, locatie) {
  return metGebruiker_(gebruikerId, function (id) {
    if (!locatie || typeof locatie.lat !== 'number' || typeof locatie.lon !== 'number') {
      return { fout: 'Ongeldige locatie' };
    }
    if (locatie.lat < -90 || locatie.lat > 90 || locatie.lon < -180 || locatie.lon > 180) {
      return { fout: 'Ongeldige coördinaten' };
    }

    var profiel = laadProfiel_(id);
    var windrichting = locatie.windrichting || { besteRanges: [], acceptabeleRanges: [] };
    var instellingen = Object.assign({}, profiel.drempelwaarden, { windrichting: windrichting });

    var dagvensterOpties = { dagvensterStartUur: profiel.dagvenster.startUur, dagvensterEindUur: profiel.dagvenster.eindUur };
    var weerData = haalWeerDataOp_(locatie.lat, locatie.lon, profiel.databronnen);
    var dagen = groepeerPerDag(weerData.urenData);
    var dagOordelen = dagen.map(function (dag) {
      var zon = zonInfoVoorDatum(weerData.zonInfo, dag.datum);
      return {
        datum: dag.datum,
        zonsopgang: zon.zonsopgang,
        zonsondergang: zon.zonsondergang,
        dagScore: berekenDagScore(dag.uren, instellingen, dagvensterOpties),
      };
    });
    return { dagen: dagOordelen };
  });
}

/** Locatie zoeken op naam. Geen sessie-check nodig: publieke geocoding-data, geen user-koppeling. */
function zoekLocatie(zoekterm) {
  return zoekLocatie_(zoekterm);
}

// GAS-specifiek: geheimen en instellingen uit Script Properties (nooit in code/repo).
// Zie SETUP.md voor hoe deze waardes in te vullen.

function getWeerliveApiKey_() {
  // Optioneel: Weerlive is een aanvullende (niet-essentiële) NL-bron. Zonder key wordt deze
  // bron simpelweg overgeslagen (zie WeerData.gs), de app blijft werken op Open-Meteo/Buienradar.
  return PropertiesService.getScriptProperties().getProperty('WEERLIVE_API_KEY') || '';
}

function getBotToken_() {
  // Optioneel: alleen nodig voor de Telegram-bot-link (zie TelegramBot.gs). Zonder token doet
  // de bot-integratie simpelweg niets — de hoofd-webapp werkt daar niet van af.
  return PropertiesService.getScriptProperties().getProperty('TELEGRAM_BOT_TOKEN') || '';
}

function getProfielenMapId_() {
  var props = PropertiesService.getScriptProperties();
  var mapId = props.getProperty('PROFIELEN_MAP_ID');
  if (mapId) return mapId;

  // Eerste keer: maak de map aan en onthoud het ID, zodat we niet steeds op naam hoeven te zoeken.
  var mapNaam = 'KiteWeerApp-Profielen';
  var mappen = DriveApp.getFoldersByName(mapNaam);
  var map = mappen.hasNext() ? mappen.next() : DriveApp.createFolder(mapNaam);
  props.setProperty('PROFIELEN_MAP_ID', map.getId());
  return map.getId();
}

// GAS-specifiek: locatie zoeken op naam (Open-Meteo Geocoding API, wereldwijd, geen key nodig).

/** Simpele eenmalige JSON-fetch — geen batching nodig, dit is de enige aanroep in dit request. */
function fetchJsonEenmalig_(url) {
  try {
    var response = UrlFetchApp.fetch(url, { muteHttpExceptions: true });
    if (response.getResponseCode() !== 200) return null;
    return JSON.parse(response.getContentText());
  } catch (e) {
    return null;
  }
}

/**
 * @param {string} zoekterm - plaatsnaam/adres, vrij ingevoerd door de gebruiker
 * @returns {Array<{naam: string, land: string, lat: number, lon: number}>}
 */
function zoekLocatie_(zoekterm) {
  var input = (zoekterm || '').trim().slice(0, 200); // inputvalidatie: lengte begrenzen
  if (!input) return [];

  var url = 'https://geocoding-api.open-meteo.com/v1/search?count=5&language=nl&name=' +
    encodeURIComponent(input);
  var json = fetchJsonEenmalig_(url);
  var resultaten = (json && json.results) || [];

  return resultaten.map(function (r) {
    var onderdelen = [r.name, r.admin1, r.country].filter(function (x) { return !!x; });
    return {
      naam: onderdelen.join(', '),
      land: r.country || '',
      lat: r.latitude,
      lon: r.longitude,
    };
  });
}

// Pure logica: combineert meerdere databronnen tot één gemiddelde waarde per variabele,
// met uitschieter-detectie, zoals beschreven in databronnen-kiteweer-app.md ("Hoe combineren").

/**
 * Middelt een set brondwaarden voor één variabele op één tijdstip.
 * @param {Array<{bron: string, waarde: number|null|undefined}>} waardenPerBron
 * @param {{uitschieterDrempel?: number}} [opties] uitschieterDrempel = max relatieve afwijking
 *   t.o.v. het gemiddelde van de overige bronnen voordat een bron genegeerd wordt (default 0.4 = 40%).
 * @returns {{gemiddelde: number|null, gebruikteBronnen: string[], genegeerdeBronnen: string[]}}
 */
function middelWaarden(waardenPerBron, opties) {
  const uitschieterDrempel = (opties && opties.uitschieterDrempel) || 0.4;

  const beschikbaar = (waardenPerBron || []).filter(
    (b) => b && b.waarde != null && !Number.isNaN(b.waarde)
  );

  if (beschikbaar.length === 0) {
    return { gemiddelde: null, gebruikteBronnen: [], genegeerdeBronnen: [] };
  }
  if (beschikbaar.length === 1) {
    return {
      gemiddelde: beschikbaar[0].waarde,
      gebruikteBronnen: [beschikbaar[0].bron],
      genegeerdeBronnen: [],
    };
  }

  const genegeerdeBronnen = [];
  let bruikbaar = beschikbaar.slice();

  // Uitschieter-detectie: verwijder net zolang de bron met de grootste relatieve afwijking
  // t.o.v. het gemiddelde als deze boven de drempel zit. Met maar 2 bronnen kun je niet meer
  // bepalen wélke van de twee de uitschieter is, dus daaronder stopt de detectie.
  while (bruikbaar.length > 2) {
    const gemiddeldeNu = bruikbaar.reduce((s, b) => s + b.waarde, 0) / bruikbaar.length;
    let ergsteKandidaat = null;
    let ergsteAfwijking = 0;
    bruikbaar.forEach((b) => {
      const afwijking = gemiddeldeNu === 0 ? 0 : Math.abs(b.waarde - gemiddeldeNu) / Math.abs(gemiddeldeNu);
      if (afwijking > ergsteAfwijking) {
        ergsteAfwijking = afwijking;
        ergsteKandidaat = b;
      }
    });
    if (!ergsteKandidaat || ergsteAfwijking <= uitschieterDrempel) break;
    genegeerdeBronnen.push(ergsteKandidaat.bron);
    bruikbaar = bruikbaar.filter((b) => b !== ergsteKandidaat);
  }

  const gemiddelde = bruikbaar.reduce((s, b) => s + b.waarde, 0) / bruikbaar.length;
  return {
    gemiddelde,
    gebruikteBronnen: bruikbaar.map((b) => b.bron),
    genegeerdeBronnen,
  };
}

/**
 * Past middelWaarden toe op een volledige uurlijkse forecast-set: een object per variabele
 * met daarin een array van {bron, reeks: number[]} (reeks = per-uur waarden, gelijke lengte/tijdstippen).
 * @returns {Object} per variabele: { gemiddelde: (number|null)[], gebruikteBronnen, genegeerdeBronnen }
 */
function middelForecastPerVariabele(bronnenPerVariabele, opties) {
  const resultaat = {};
  Object.keys(bronnenPerVariabele || {}).forEach((variabele) => {
    const bronnen = bronnenPerVariabele[variabele] || [];
    const aantalUren = bronnen.reduce((max, b) => Math.max(max, (b.reeks || []).length), 0);
    const perUur = [];
    for (let uur = 0; uur < aantalUren; uur += 1) {
      const waardenPerBron = bronnen.map((b) => ({ bron: b.bron, waarde: (b.reeks || [])[uur] }));
      perUur.push(middelWaarden(waardenPerBron, opties));
    }
    resultaat[variabele] = {
      gemiddelde: perUur.map((u) => u.gemiddelde),
      gebruikteBronnen: perUur.map((u) => u.gebruikteBronnen),
      genegeerdeBronnen: perUur.map((u) => u.genegeerdeBronnen),
    };
  });
  return resultaat;
}

// Pure logica: parseert de rauwe JSON-responses van elke databron (databronnen-kiteweer-app.md)
// naar een genormaliseerd formaat dat scoreBerekening.js/bronnenMiddeling.js verwacht.
// Geen UrlFetchApp hier — het ophalen gebeurt in src/gas/WeerData.gs, dat deze functies aanroept.


/** WMO weather_code 95/96/99 = onweer (zie https://open-meteo.com/en/docs, WMO-tabel). */
function weerCodeIsOnweer(code) {
  return code === 95 || code === 96 || code === 99;
}

/**
 * Open-Meteo Forecast API — hoofdbron voor wind, onweer/buien, luchttemperatuur, zicht.
 * Verwacht dat de call is gedaan met `wind_speed_unit=kn` (zie WeerData.gs), zodat hier
 * geen conversie nodig is. `daily` (zonsopgang/-ondergang) is een aparte, dag-niveau reeks
 * naast de uurlijkse `hourly`-reeks — zie WeerData.gs (`&daily=sunrise,sunset`).
 */
function parseOpenMeteoForecast(json) {
  const h = (json && json.hourly) || {};
  const dagelijks = (json && json.daily) || {};
  const tijdstippen = h.time || [];
  return {
    bron: 'open-meteo',
    tijdstippen,
    windKnopen: h.wind_speed_10m || tijdstippen.map(() => null),
    windvlaagKnopen: h.wind_gusts_10m || tijdstippen.map(() => null),
    windrichtingGraden: h.wind_direction_10m || tijdstippen.map(() => null),
    onweerAanwezig: (h.weather_code || tijdstippen.map(() => null)).map(weerCodeIsOnweer),
    neerslagKans: (h.precipitation_probability || tijdstippen.map(() => null)).map((p) =>
      p == null ? null : p / 100
    ),
    luchttemperatuurCelsius: h.temperature_2m || tijdstippen.map(() => null),
    zichtKm: (h.visibility || tijdstippen.map(() => null)).map((m) => (m == null ? null : m / 1000)),
    bewolkingPercent: h.cloud_cover || tijdstippen.map(() => null),
    dagInfo: {
      datums: dagelijks.time || [],
      zonsopgang: dagelijks.sunrise || [],
      zonsondergang: dagelijks.sunset || [],
    },
  };
}

/** Open-Meteo Marine API — watertemperatuur en golfhoogte, wereldwijd op zee/kust. */
function parseOpenMeteoMarine(json) {
  const h = (json && json.hourly) || {};
  const tijdstippen = h.time || [];
  return {
    bron: 'open-meteo-marine',
    tijdstippen,
    watertemperatuurCelsius: h.sea_surface_temperature || tijdstippen.map(() => null),
    golfhoogteMeter: h.wave_height || tijdstippen.map(() => null),
  };
}

/**
 * Buienradar JSON-feed — actuele waarnemingen per meetstation (geen forecast).
 * Kiest het dichtstbijzijnde station t.o.v. de opgegeven lat/lon.
 */
function parseBuienradarFeed(json, lat, lon) {
  const stations = (json && json.actual && json.actual.stationmeasurements) || [];
  const station = dichtstbijzijnde(lat, lon, stations);
  if (!station) return null;
  return {
    bron: 'buienradar',
    tijdstip: station.timestamp,
    stationnaam: station.stationname,
    afstandKm: null, // door de aanroeper te berekenen indien gewenst
    windKnopen: msNaarKnopen(station.windspeed),
    windvlaagKnopen: msNaarKnopen(station.windgusts),
    windrichtingGraden: station.winddirectiondegrees != null ? station.winddirectiondegrees : null,
    luchttemperatuurCelsius: station.temperature != null ? station.temperature : null,
    zichtKm: station.visibility != null ? station.visibility / 1000 : null,
  };
}

/**
 * Buienradar raintext — neerslag-nowcasting per 5 min, komend ~2 uur. Regels: "waarde|HH:mm".
 * Conversie dBZ-achtige waarde -> mm/uur volgens de bekende Buienradar-formule.
 */
function parseBuienradarRaintext(tekst) {
  const regels = (tekst || '').split('\n').map((r) => r.trim()).filter(Boolean);
  return regels.map((regel) => {
    const [waardeStr, tijd] = regel.split('|');
    const waarde = Number(waardeStr);
    const mmPerUur = Number.isFinite(waarde) ? Math.pow(10, (waarde - 109) / 32) : null;
    return { tijd, mmPerUur };
  });
}

/**
 * Weerlive.nl API (v2, json-data-10min.php) — actuele waarneming + korte verwachting, alleen NL.
 * Vereist een gratis API-key (zie SETUP.md). Veldnamen zijn gebaseerd op de publieke Weerlive-
 * documentatie en zijn NIET getest tegen een live response (geen key beschikbaar tijdens bouw) —
 * zie "Aannames" in README.md. De GAS-laag vangt afwijkende/ontbrekende velden af (best effort:
 * bij een onverwachte vorm worden de betreffende waarden als niet-beschikbaar (null) behandeld,
 * zodat deze bron simpelweg wordt overgeslagen in de middeling i.p.v. de hele call te laten falen).
 */
function parseWeerlive(json) {
  const data = json && Array.isArray(json.liveweer) ? json.liveweer[0] : null;
  if (!data) return null;
  return {
    bron: 'weerlive',
    tijdstip: null,
    windKnopen: data.windknp != null ? Number(data.windknp) : null,
    windrichtingGraden: data.windrgr != null ? Number(data.windrgr) : null,
    luchttemperatuurCelsius: data.temp != null ? Number(data.temp) : null,
    zichtKm: data.zicht != null ? Number(data.zicht) : null,
  };
}

/**
 * Ontrafelt Windfinder's [tag, waarde]-tuple-formaat (hun eigen client-state-serialisatie) tot
 * gewone JS-waarden/objecten/arrays. Elk niveau — ook geneste objectvelden — kan zo'n tuple zijn.
 */
function ontrafelWindfinderTuple(node) {
  if (Array.isArray(node) && node.length === 2 && typeof node[0] === 'number') {
    return ontrafelWindfinderTuple(node[1]);
  }
  if (Array.isArray(node)) return node.map(ontrafelWindfinderTuple);
  if (node && typeof node === 'object') {
    const resultaat = {};
    Object.keys(node).forEach((k) => { resultaat[k] = ontrafelWindfinderTuple(node[k]); });
    return resultaat;
  }
  return node;
}

/**
 * Windfinder.com forecast-pagina (bv. https://www.windfinder.com/forecast/rockanje) — geen
 * publieke API, maar de volledige meerdaagse voorspelling (wind, golven, getij) staat als JSON
 * ingebakken in de server-gerenderde HTML zelf (voor hun eigen Astro-component-hydratie), in het
 * "props"-attribuut van het <astro-island> voor het "ForecastDataInit"-component. Geen losse
 * API-call of JavaScript-uitvoering nodig — één keer de paginabron parsen volstaat.
 * Waarden zijn in SI-eenheden (m/s, meter, Kelvin) ongeacht de weergave-eenheid van de site zelf.
 * Levert 3-uurlijkse punten (geen uurlijkse reeks zoals Open-Meteo).
 * Zie README.md "Aannames" voor de juridische afweging (robots.txt staat /forecast/ toe, maar
 * dat zegt niets over hergebruiksrecht van de data — bewust alleen gebruikt op uitdrukkelijk
 * verzoek, en uit te zetten via de bronnen-instelling in de app).
 */
function parseWindfinderForecast(html) {
  const match = /<astro-island[^>]*component-url="[^"]*ForecastDataInit[^"]*"[^>]*props="([^"]*)"/.exec(
    html || ''
  );
  if (!match) return null;

  let json;
  try {
    const decoded = match[1]
      .replace(/&quot;/g, '"')
      .replace(/&#39;/g, "'")
      .replace(/&lt;/g, '<')
      .replace(/&gt;/g, '>')
      .replace(/&amp;/g, '&');
    json = JSON.parse(decoded);
  } catch (e) {
    return null;
  }

  const dagen = (ontrafelWindfinderTuple(json.fcSectionData) || [])[0] || [];
  const uren = [];
  dagen.forEach((dag) => {
    (dag.horizons || []).forEach((horizon) => {
      const fc = horizon.fcData || {};
      if (!fc.dtl) return;
      uren.push({
        tijdstip: fc.dtl,
        windKnopen: fc.ws != null ? msNaarKnopen(fc.ws) : null,
        windvlaagKnopen: fc.wg != null ? msNaarKnopen(fc.wg) : null,
        windrichtingGraden: fc.wd != null ? fc.wd : null,
        golfhoogteMeter: fc.wah != null ? fc.wah : null,
      });
    });
  });
  uren.sort((a, b) => new Date(a.tijdstip).getTime() - new Date(b.tijdstip).getTime());

  return {
    bron: 'windfinder',
    tijdstippen: uren.map((u) => u.tijdstip),
    windKnopen: uren.map((u) => u.windKnopen),
    windvlaagKnopen: uren.map((u) => u.windvlaagKnopen),
    windrichtingGraden: uren.map((u) => u.windrichtingGraden),
    golfhoogteMeter: uren.map((u) => u.golfhoogteMeter),
  };
}

/** Haalt één ProcesType (bv. "meting" of "verwachting") uit een RWS OphalenWaarnemingen-respons. */
function kiesRwsProcesType(json, procesType) {
  const lijst = (json && json.WaarnemingenLijst) || [];
  const gekozen = lijst.filter((w) => w.AquoMetadata && w.AquoMetadata.ProcesType === procesType)[0];
  if (!gekozen) return { tijdstippen: [], waarden: [] };
  const metingen = gekozen.MetingenLijst || [];
  return {
    tijdstippen: metingen.map((m) => m.Tijdstip),
    waarden: metingen.map((m) => (m.Meetwaarde ? m.Meetwaarde.Waarde_Numeriek : null)),
  };
}

/**
 * Rijkswaterstaat meet naast getij ook wind (WINDSHD/WINDRTG) op hetzelfde meetpunt — zelfde
 * aanpak als Windfinder: ProcesType "verwachting" is een extra, onafhankelijke voorspellingsreeks
 * (eigen tijdstippen, per uur genaderd door forecastSamenstellen.js). Windrichting wordt op
 * exact tijdstip gekoppeld aan windsnelheid (aparte API-calls per grootheid, dus niet zomaar
 * index-voor-index uit te lijnen).
 */
function parseRwsWindVerwachting(windshdJson, windrtgJson) {
  const snelheid = kiesRwsProcesType(windshdJson, 'verwachting');
  const richting = kiesRwsProcesType(windrtgJson, 'verwachting');
  const richtingPerTijdstip = new Map();
  richting.tijdstippen.forEach((t, i) => richtingPerTijdstip.set(t, richting.waarden[i]));
  return {
    bron: 'rws-wind-verwachting',
    tijdstippen: snelheid.tijdstippen,
    windKnopen: snelheid.waarden.map((w) => (w != null ? msNaarKnopen(w) : null)),
    windrichtingGraden: snelheid.tijdstippen.map((t) => {
      const w = richtingPerTijdstip.get(t);
      return w != null ? w : null;
    }),
  };
}

/**
 * RWS wind-"meting" (ProcesType "meting") — de daadwerkelijk gemeten, actuele wind op het
 * meetpunt. Geen forecast-reeks maar één momentopname (het laatste meetpunt), net als
 * Buienradar/Weerlive: alleen bruikbaar als "nu"-cross-check.
 */
function parseRwsWindMeting(windshdJson, windrtgJson) {
  const snelheid = kiesRwsProcesType(windshdJson, 'meting');
  const richting = kiesRwsProcesType(windrtgJson, 'meting');
  if (snelheid.waarden.length === 0) return null;
  const laatsteWindKnopen = snelheid.waarden[snelheid.waarden.length - 1];
  const laatsteRichting = richting.waarden.length ? richting.waarden[richting.waarden.length - 1] : null;
  return {
    bron: 'rws-wind-meting',
    tijdstip: snelheid.tijdstippen[snelheid.tijdstippen.length - 1],
    windKnopen: laatsteWindKnopen != null ? msNaarKnopen(laatsteWindKnopen) : null,
    windrichtingGraden: laatsteRichting,
  };
}

// Pure logica: evaluatie van gemeten waarden tegen de (instelbare) drempelwaarden
// uit criteria-kiteweer-app.md. Geen GAS-afhankelijkheden, puur JS/Node-testbaar.
//
// Alle numerieke drempelwaarden starten LEEG (null) — de gebruiker moet ze bewust zelf instellen
// in plaats van (mogelijk misleidende) standaardwaarden te vertrouwen bij een veiligheidskritische
// go/no-go-beslissing. Elke evaluatiefunctie behandelt een ontbrekende drempel als
// 'niet-geconfigureerd' (neutraal, telt niet als no-go, maar telt ook niet mee als een echte
// beoordeling) — zie heeftEssentieleConfiguratie() voor de check die de UI gebruikt om de
// gebruiker daarop te wijzen.

/** Drempelwaarden-"vorm": alle tunable getallen leeg, op een paar bewust veilige defaults na. */
function standaardDrempelwaarden() {
  return {
    windsnelheid: { minimum: null, ideaalOnder: null, ideaalBoven: null, maximum: null },
    windrichting: { besteRanges: [], acceptabeleRanges: [] },
    windvlagen: { waarschuwingVlaagfactor: null, maxVlaagfactor: null },
    // hardNoGo blijft standaard aan: "onweer = altijd gevaarlijk" is een veiligheidsvangnet,
    // geen persoonlijke voorkeur zoals de andere drempels.
    onweer: { hardNoGo: true, neerslagWaarschuwingDrempel: null },
    luchttemperatuur: { minimumComfortabel: null },
    watertemperatuur: { minimumComfortabel: null, minimumMetWetsuit: null },
    golfhoogte: { maximum: null, voorkeurGolven: false },
    getij: { voorkeur: 'geen' },
    zicht: { minimum: null },
  };
}

/**
 * De essentiële drempels (windsnelheid + windvlagen — windrichting is per-locatie, onweer heeft
 * al een veilige default) die de gebruiker minimaal zelf moet instellen voordat een score/kleur
 * een betrouwbare go/no-go-betekenis heeft. Gebruikt door de UI om een "eerst instellen"-banner
 * te tonen i.p.v. stilzwijgend met halve/onjuiste aannames te rekenen.
 */
function heeftEssentieleConfiguratie(drempelwaarden) {
  const w = (drempelwaarden && drempelwaarden.windsnelheid) || {};
  const v = (drempelwaarden && drempelwaarden.windvlagen) || {};
  return (
    w.minimum != null &&
    w.ideaalOnder != null &&
    w.ideaalBoven != null &&
    v.maxVlaagfactor != null &&
    v.waarschuwingVlaagfactor != null
  );
}

function clamp01(x) {
  return Math.max(0, Math.min(1, x));
}

/**
 * Windsnelheid is essentieel: onder het minimum is een harde no-go.
 * Score loopt lineair op tot het ideale bereik en blijft 1 binnen het ideale bereik.
 * Boven een eventueel ingesteld maximum is het ook een no-go (te hard voor de gekozen kite).
 */
function evalueerWindsnelheid(knopen, instellingen) {
  const i = instellingen || standaardDrempelwaarden().windsnelheid;
  if (knopen == null) return { status: 'onbekend', score: 0, noGo: false };
  if (i.minimum == null || i.ideaalOnder == null || i.ideaalBoven == null) {
    return { status: 'niet-geconfigureerd', score: 0.5, noGo: false };
  }
  if (knopen < i.minimum) return { status: 'no-go', score: 0, noGo: true, reden: 'Te weinig wind' };
  if (i.maximum != null && knopen > i.maximum) {
    return { status: 'no-go', score: 0, noGo: true, reden: 'Te veel wind' };
  }
  if (knopen >= i.ideaalOnder && knopen <= i.ideaalBoven) {
    return { status: 'ideaal', score: 1, noGo: false };
  }
  if (knopen < i.ideaalOnder) {
    const score = clamp01((knopen - i.minimum) / (i.ideaalOnder - i.minimum));
    return { status: 'bruikbaar', score, noGo: false };
  }
  // Boven ideaalBoven (en onder/op een eventueel maximum): geleidelijk afnemende score.
  const bovengrens = i.maximum != null ? i.maximum : i.ideaalBoven * 1.5;
  const score = clamp01(1 - (knopen - i.ideaalBoven) / (bovengrens - i.ideaalBoven));
  return { status: 'gevorderd', score, noGo: false };
}

/** Normaliseert een hoek naar het bereik [0, 360). */
function normaliseerGraden(graden) {
  return ((graden % 360) + 360) % 360;
}

/** Ligt `graden` in het (mogelijk over 360/0 heen wikkelende) bereik [start, eind]? */
function inGradenBereik(graden, start, eind) {
  const g = normaliseerGraden(graden);
  const s = normaliseerGraden(start);
  const e = normaliseerGraden(eind);
  if (s <= e) return g >= s && g <= e;
  return g >= s || g <= e; // bereik wikkelt over 0/360 heen
}

/**
 * Windrichting is essentieel en spot-afhankelijk (cross-shore t.o.v. de kustlijn).
 * `instellingen.besteRanges`/`acceptabeleRanges` zijn arrays van [start, eind] in graden,
 * ingesteld per gekozen locatie op basis van de kustoriëntatie.
 * Buiten beide bereiken = offshore/cross-offshore = harde no-go.
 * Lege bereik-arrays betekenen "nog niet geconfigureerd voor deze locatie" -> niet beoordeelbaar.
 */
function evalueerWindrichting(graden, instellingen) {
  const i = instellingen || standaardDrempelwaarden().windrichting;
  if (graden == null) return { status: 'onbekend', score: 0, noGo: false };
  const geenConfig = (!i.besteRanges || i.besteRanges.length === 0)
    && (!i.acceptabeleRanges || i.acceptabeleRanges.length === 0);
  if (geenConfig) return { status: 'niet-geconfigureerd', score: 0.5, noGo: false };

  const isBeste = (i.besteRanges || []).some(([s, e]) => inGradenBereik(graden, s, e));
  if (isBeste) return { status: 'beste', score: 1, noGo: false };

  const isAcceptabel = (i.acceptabeleRanges || []).some(([s, e]) => inGradenBereik(graden, s, e));
  if (isAcceptabel) return { status: 'acceptabel', score: 0.6, noGo: false };

  return { status: 'no-go', score: 0, noGo: true, reden: 'Offshore of cross-offshore wind' };
}

/**
 * Windvlagen: vlaagfactor = (vlaag - gemiddelde) / gemiddelde.
 * Boven maxVlaagfactor is een harde no-go, tussen waarschuwing en max is een waarschuwing
 * (weegt mee in de score, blokkeert niet).
 */
function evalueerWindvlagen(gemiddeldeKnopen, vlaagKnopen, instellingen) {
  const i = instellingen || standaardDrempelwaarden().windvlagen;
  if (gemiddeldeKnopen == null || vlaagKnopen == null || gemiddeldeKnopen === 0) {
    return { status: 'onbekend', score: 0, noGo: false, vlaagfactor: null };
  }
  if (i.maxVlaagfactor == null || i.waarschuwingVlaagfactor == null) {
    return { status: 'niet-geconfigureerd', score: 0.5, noGo: false, vlaagfactor: null };
  }
  const vlaagfactor = (vlaagKnopen - gemiddeldeKnopen) / gemiddeldeKnopen;
  if (vlaagfactor > i.maxVlaagfactor) {
    return { status: 'no-go', score: 0, noGo: true, vlaagfactor, reden: 'Te grillige windvlagen' };
  }
  if (vlaagfactor > i.waarschuwingVlaagfactor) {
    const score = clamp01(1 - (vlaagfactor - i.waarschuwingVlaagfactor) / (i.maxVlaagfactor - i.waarschuwingVlaagfactor));
    return { status: 'waarschuwing', score, noGo: false, vlaagfactor };
  }
  return { status: 'laag-risico', score: 1, noGo: false, vlaagfactor };
}

/**
 * Onweer/buien: onweer is standaard altijd een harde no-go (uit te zetten per profiel, dit is
 * de enige drempel die niet blanco start — zie standaardDrempelwaarden()).
 * Een hoge neerslagkans zonder onweer is een waarschuwing, geen no-go — alleen als er een
 * drempel is ingesteld; zonder ingestelde drempel wordt de neerslagkans genegeerd (niet als
 * automatisch "wel" of "geen" waarschuwing behandeld).
 */
function evalueerOnweer(onweerAanwezig, neerslagKans, instellingen) {
  const i = instellingen || standaardDrempelwaarden().onweer;
  if (onweerAanwezig && i.hardNoGo !== false) {
    return { status: 'no-go', score: 0, noGo: true, reden: 'Onweer aanwezig of voorspeld' };
  }
  if (i.neerslagWaarschuwingDrempel != null && neerslagKans != null && neerslagKans > i.neerslagWaarschuwingDrempel) {
    return { status: 'waarschuwing', score: 0.5, noGo: false, reden: 'Hoge neerslagkans' };
  }
  return { status: 'ok', score: 1, noGo: false };
}

function evalueerLuchttemperatuur(celsius, instellingen) {
  const i = instellingen || standaardDrempelwaarden().luchttemperatuur;
  if (celsius == null) return { status: 'onbekend', score: 0.5, noGo: false };
  if (i.minimumComfortabel == null) return { status: 'niet-geconfigureerd', score: 0.5, noGo: false };
  if (celsius >= i.minimumComfortabel) return { status: 'comfortabel', score: 1, noGo: false };
  const score = clamp01(0.5 + (celsius - i.minimumComfortabel) / 20);
  return { status: 'kouder', score, noGo: false };
}

function evalueerWatertemperatuur(celsius, instellingen) {
  const i = instellingen || standaardDrempelwaarden().watertemperatuur;
  if (celsius == null) return { status: 'onbekend', score: 0.5, noGo: false };
  if (i.minimumComfortabel == null || i.minimumMetWetsuit == null) {
    return { status: 'niet-geconfigureerd', score: 0.5, noGo: false };
  }
  if (celsius >= i.minimumComfortabel) return { status: 'comfortabel-zonder-wetsuit', score: 1, noGo: false };
  if (celsius >= i.minimumMetWetsuit) {
    const score = clamp01(0.5 + (celsius - i.minimumMetWetsuit) / (2 * (i.minimumComfortabel - i.minimumMetWetsuit)));
    return { status: 'met-wetsuit-doenlijk', score, noGo: false };
  }
  return { status: 'te-koud', score: 0.1, noGo: false };
}

function evalueerGolfhoogte(meter, instellingen) {
  const i = instellingen || standaardDrempelwaarden().golfhoogte;
  if (meter == null) return { status: 'onbekend', score: 0.5, noGo: false };
  if (i.maximum == null) return { status: 'niet-geconfigureerd', score: 0.5, noGo: false };
  if (i.voorkeurGolven) {
    const score = clamp01(meter / i.maximum);
    return { status: score >= 1 ? 'golven-gewenst' : 'te-vlak', score, noGo: false };
  }
  if (meter <= 0.5) return { status: 'vlak-water', score: 1, noGo: false };
  if (meter <= i.maximum) return { status: 'gemiddeld', score: 0.7, noGo: false };
  const score = clamp01(1 - (meter - i.maximum) / i.maximum);
  return { status: 'hoog', score, noGo: false };
}

function evalueerGetij(getijStatus, instellingen) {
  const i = instellingen || standaardDrempelwaarden().getij;
  if (!i.voorkeur || i.voorkeur === 'geen' || getijStatus == null) {
    return { status: 'geen-voorkeur', score: 1, noGo: false };
  }
  return { status: getijStatus, score: getijStatus === i.voorkeur ? 1 : 0.4, noGo: false };
}

function evalueerZicht(km, instellingen) {
  const i = instellingen || standaardDrempelwaarden().zicht;
  if (km == null) return { status: 'onbekend', score: 0.5, noGo: false };
  if (i.minimum == null) return { status: 'niet-geconfigureerd', score: 0.5, noGo: false };
  if (km < i.minimum) return { status: 'onvoldoende', score: 0.2, noGo: false };
  return { status: 'voldoende', score: 1, noGo: false };
}

// Pure logica: eenheid-conversies, gedeeld door de bron-parsers.

const KNOPEN_PER_MS = 1.9438444924;
const KNOPEN_PER_KMH = 0.5399568;

function msNaarKnopen(ms) {
  return ms == null ? null : ms * KNOPEN_PER_MS;
}

function kmhNaarKnopen(kmh) {
  return kmh == null ? null : kmh * KNOPEN_PER_KMH;
}

/** Haversine-afstand in kilometers tussen twee lat/lon-punten. */
function afstandKm(lat1, lon1, lat2, lon2) {
  const R = 6371;
  const dLat = ((lat2 - lat1) * Math.PI) / 180;
  const dLon = ((lon2 - lon1) * Math.PI) / 180;
  const a =
    Math.sin(dLat / 2) ** 2 +
    Math.cos((lat1 * Math.PI) / 180) * Math.cos((lat2 * Math.PI) / 180) * Math.sin(dLon / 2) ** 2;
  return 2 * R * Math.asin(Math.sqrt(a));
}

/** Vindt het dichtstbijzijnde element in `punten` (elk met .lat/.lon) t.o.v. (lat, lon). */
function dichtstbijzijnde(lat, lon, punten) {
  if (!punten || punten.length === 0) return null;
  return punten.reduce((beste, p) => {
    const afstand = afstandKm(lat, lon, p.lat, p.lon);
    return !beste || afstand < beste.afstand ? { punt: p, afstand } : beste;
  }, null).punt;
}

const KOMPAS_PUNTEN = [
  'N', 'NNO', 'NO', 'ONO', 'O', 'OZO', 'ZO', 'ZZO',
  'Z', 'ZZW', 'ZW', 'WZW', 'W', 'WNW', 'NW', 'NNW',
];

/** Zet een windrichting in graden om naar het dichtstbijzijnde 16-punts kompaslabel (bv. "ZZW"). */
function windrichtingKompas(graden) {
  if (graden == null || Number.isNaN(graden)) return null;
  const g = ((graden % 360) + 360) % 360;
  return KOMPAS_PUNTEN[Math.round(g / 22.5) % 16];
}

// Pure logica: voegt de genormaliseerde output van bronParsers.js per uur samen tot de
// uurData-structuur die scoreBerekening.berekenUurScore/berekenDagScore verwacht, en middelt
// daarbij over de beschikbare bronnen (zie bronnenMiddeling.js).
//
// Open-Meteo (forecast + marine) is de enige bron met een echte 3-daagse uurlijkse reeks en
// vormt daarom de tijdlijn. Buienradar/Weerlive leveren alleen een actuele waarneming ("nu") en
// worden uitsluitend meegemiddeld op het uur dat het dichtst bij het huidige tijdstip ligt —
// conform "Vandaag/nu" in databronnen-kiteweer-app.md.


function vindDichtstbijzijndUurIndex(tijdstippenIso, huidigTijdstipIso) {
  if (!huidigTijdstipIso || !tijdstippenIso || tijdstippenIso.length === 0) return -1;
  const nu = new Date(huidigTijdstipIso).getTime();
  let besteIndex = -1;
  let besteVerschil = Infinity;
  tijdstippenIso.forEach((t, i) => {
    const verschil = Math.abs(new Date(t).getTime() - nu);
    if (verschil < besteVerschil) {
      besteVerschil = verschil;
      besteIndex = i;
    }
  });
  return besteIndex;
}

function indexeerOpTijdstip(reeks) {
  const map = new Map();
  (reeks && reeks.tijdstippen ? reeks.tijdstippen : []).forEach((t, i) => map.set(t, i));
  return map;
}

/**
 * Bouwt een opzoekfunctie voor een bron met een eigen (grovere) tijdreeks dan Open-Meteo's
 * uurlijkse tijdlijn — geeft de index van het dichtstbijzijnde punt terug, of -1 als niets
 * binnen `maxAfstandMs` ligt. Gebruikt voor Windfinder en de RWS-windverwachting.
 */
function maakNaburigeIndexZoeker(bron, maxAfstandMs) {
  return function (doelTijdstipIso) {
    if (!bron || !bron.tijdstippen || bron.tijdstippen.length === 0) return -1;
    const dichtstbijIndex = vindDichtstbijzijndUurIndex(bron.tijdstippen, doelTijdstipIso);
    if (dichtstbijIndex === -1) return -1;
    const afstandMs = Math.abs(
      new Date(bron.tijdstippen[dichtstbijIndex]).getTime() - new Date(doelTijdstipIso).getTime()
    );
    return afstandMs <= maxAfstandMs ? dichtstbijIndex : -1;
  };
}

/**
 * @param {Object} bronnen
 *   - openMeteo: output van parseOpenMeteoForecast (verplicht, vormt de tijdlijn)
 *   - openMeteoMarine: output van parseOpenMeteoMarine (optioneel)
 *   - buienradar: output van parseBuienradarFeed (optioneel, "nu"-snapshot)
 *   - weerlive: output van parseWeerlive (optioneel, "nu"-snapshot)
 *   - windfinder: output van parseWindfinderForecast (optioneel; eigen 3-uurlijkse tijdstippen)
 *   - rwsWindVerwachting: output van parseRwsWindVerwachting (optioneel; extra windvoorspelling)
 *   - rwsWindMeting: output van parseRwsWindMeting (optioneel, "nu"-snapshot, actuele wind)
 *   - rwsGetij: output van parseRwsGetij (optioneel; eigen tijdstippen, meestal elke 10 min)
 *   - huidigTijdstipIso: ISO-tijdstip van "nu", om buienradar/weerlive op het juiste uur te plakken
 * @param {Object} [middelingOpties] doorgegeven aan middelWaarden (bv. uitschieterDrempel)
 * @returns {Array<{tijdstip: string, uurData: Object, bronDetails: Object}>}
 */
function samenstellenUrenData(bronnen, middelingOpties) {
  const openMeteo = bronnen.openMeteo || { tijdstippen: [] };
  const tijdstippen = openMeteo.tijdstippen || [];
  const marineIndex = indexeerOpTijdstip(bronnen.openMeteoMarine);
  const nuIndex = vindDichtstbijzijndUurIndex(tijdstippen, bronnen.huidigTijdstipIso);

  // RWS levert eigen tijdstippen (meestal 10-minutenreeks), dus per Open-Meteo-uur wordt de
  // dichtstbijzijnde RWS-classificatie opgezocht i.p.v. een exacte tijdstip-match.
  const rwsGetij = bronnen.rwsGetij;
  const getijStatusPerRwsTijdstip = rwsGetij ? classificeerGetijStatus(rwsGetij.waterstandCm) : [];
  const rwsGetijIndexVoorTijdstip = maakNaburigeIndexZoeker(rwsGetij, 60 * 60 * 1000);
  function getijStatusVoorTijdstip(doelTijdstipIso) {
    const index = rwsGetijIndexVoorTijdstip(doelTijdstipIso);
    return index === -1 ? null : getijStatusPerRwsTijdstip[index];
  }

  // Windfinder en de RWS-windverwachting leveren allebei een eigen (geen uurlijkse) reeks — geen
  // "nu"-snapshot zoals Buienradar/Weerlive, wel een echte meerdaagse voorspelling zoals
  // Open-Meteo — per Open-Meteo-uur wordt het dichtstbijzijnde punt gezocht.
  const windfinder = bronnen.windfinder;
  const windfinderIndexVoorTijdstip = maakNaburigeIndexZoeker(windfinder, 90 * 60 * 1000);
  const rwsWindVerwachting = bronnen.rwsWindVerwachting;
  const rwsWindIndexVoorTijdstip = maakNaburigeIndexZoeker(rwsWindVerwachting, 60 * 60 * 1000);

  return tijdstippen.map((tijdstip, i) => {
    const isNu = i === nuIndex;
    const windfinderI = windfinderIndexVoorTijdstip(tijdstip);

    const windBronnen = [{ bron: 'open-meteo', waarde: openMeteo.windKnopen[i] }];
    const windrichtingBronnen = [{ bron: 'open-meteo', waarde: openMeteo.windrichtingGraden[i] }];
    const windvlaagBronnen = [{ bron: 'open-meteo', waarde: openMeteo.windvlaagKnopen[i] }];
    const luchttempBronnen = [{ bron: 'open-meteo', waarde: openMeteo.luchttemperatuurCelsius[i] }];
    const zichtBronnen = [{ bron: 'open-meteo', waarde: openMeteo.zichtKm[i] }];

    const marineI = marineIndex.get(tijdstip);
    const marine = bronnen.openMeteoMarine;
    const golfhoogteBronnen =
      marineI != null ? [{ bron: 'open-meteo-marine', waarde: marine.golfhoogteMeter[marineI] }] : [];

    if (isNu && bronnen.buienradar) {
      windBronnen.push({ bron: 'buienradar', waarde: bronnen.buienradar.windKnopen });
      windrichtingBronnen.push({ bron: 'buienradar', waarde: bronnen.buienradar.windrichtingGraden });
      luchttempBronnen.push({ bron: 'buienradar', waarde: bronnen.buienradar.luchttemperatuurCelsius });
      zichtBronnen.push({ bron: 'buienradar', waarde: bronnen.buienradar.zichtKm });
    }
    if (isNu && bronnen.weerlive) {
      windBronnen.push({ bron: 'weerlive', waarde: bronnen.weerlive.windKnopen });
      windrichtingBronnen.push({ bron: 'weerlive', waarde: bronnen.weerlive.windrichtingGraden });
      luchttempBronnen.push({ bron: 'weerlive', waarde: bronnen.weerlive.luchttemperatuurCelsius });
      zichtBronnen.push({ bron: 'weerlive', waarde: bronnen.weerlive.zichtKm });
    }
    if (windfinderI !== -1) {
      windBronnen.push({ bron: 'windfinder', waarde: windfinder.windKnopen[windfinderI] });
      windrichtingBronnen.push({ bron: 'windfinder', waarde: windfinder.windrichtingGraden[windfinderI] });
      windvlaagBronnen.push({ bron: 'windfinder', waarde: windfinder.windvlaagKnopen[windfinderI] });
      golfhoogteBronnen.push({ bron: 'windfinder', waarde: windfinder.golfhoogteMeter[windfinderI] });
    }
    const rwsWindI = rwsWindIndexVoorTijdstip(tijdstip);
    if (rwsWindI !== -1) {
      windBronnen.push({ bron: 'rws-wind-verwachting', waarde: rwsWindVerwachting.windKnopen[rwsWindI] });
      windrichtingBronnen.push({ bron: 'rws-wind-verwachting', waarde: rwsWindVerwachting.windrichtingGraden[rwsWindI] });
    }
    // RWS-"meting" is een echte actuele waarneming (geen voorspelling) — zoals Buienradar/Weerlive
    // alleen op het "nu"-uur meegewogen, als extra onafhankelijke cross-check van de actuele wind.
    if (isNu && bronnen.rwsWindMeting) {
      windBronnen.push({ bron: 'rws-wind-meting', waarde: bronnen.rwsWindMeting.windKnopen });
      windrichtingBronnen.push({ bron: 'rws-wind-meting', waarde: bronnen.rwsWindMeting.windrichtingGraden });
    }

    const windMiddeling = middelWaarden(windBronnen, middelingOpties);
    const windrichtingMiddeling = middelWaarden(windrichtingBronnen, middelingOpties);
    const windvlaagMiddeling = middelWaarden(windvlaagBronnen, middelingOpties);
    const luchttempMiddeling = middelWaarden(luchttempBronnen, middelingOpties);
    const zichtMiddeling = middelWaarden(zichtBronnen, middelingOpties);
    const golfhoogteMiddeling = middelWaarden(golfhoogteBronnen, middelingOpties);

    return {
      tijdstip,
      uurData: {
        windKnopen: windMiddeling.gemiddelde,
        windvlaagKnopen: windvlaagMiddeling.gemiddelde,
        windrichtingGraden: windrichtingMiddeling.gemiddelde,
        onweerAanwezig: openMeteo.onweerAanwezig[i],
        neerslagKans: openMeteo.neerslagKans[i],
        luchttemperatuurCelsius: luchttempMiddeling.gemiddelde,
        watertemperatuurCelsius: marineI != null ? marine.watertemperatuurCelsius[marineI] : null,
        golfhoogteMeter: golfhoogteMiddeling.gemiddelde,
        getijStatus: getijStatusVoorTijdstip(tijdstip),
        zichtKm: zichtMiddeling.gemiddelde,
      },
      bronDetails: {
        wind: windMiddeling,
        windrichting: windrichtingMiddeling,
        windvlagen: windvlaagMiddeling,
        luchttemperatuur: luchttempMiddeling,
        zicht: zichtMiddeling,
        golfhoogte: golfhoogteMiddeling,
      },
    };
  });
}

/** Groepeert een urenData-array (van samenstellenUrenData) per kalenderdag (YYYY-MM-DD, lokale tijd in het ISO-tijdstip). */
function groepeerPerDag(urenData) {
  const perDag = new Map();
  (urenData || []).forEach((uur) => {
    const datum = (uur.tijdstip || '').slice(0, 10);
    if (!perDag.has(datum)) perDag.set(datum, []);
    perDag.get(datum).push(uur);
  });
  return Array.from(perDag.entries()).map(([datum, uren]) => ({ datum, uren }));
}

/**
 * Zoekt zonsopgang/-ondergang (ISO-tijdstippen) voor één kalenderdag op in Open-Meteo's
 * `dagInfo` (zie parseOpenMeteoForecast) — een aparte dag-niveau reeks naast de uurlijkse
 * tijdlijn, dus hier op datum (niet op uur-index) opgezocht.
 * @param {{datums: string[], zonsopgang: string[], zonsondergang: string[]}} [dagInfo]
 * @param {string} datum YYYY-MM-DD
 */
function zonInfoVoorDatum(dagInfo, datum) {
  const index = dagInfo && dagInfo.datums ? dagInfo.datums.indexOf(datum) : -1;
  if (index === -1) return { zonsopgang: null, zonsondergang: null };
  return {
    zonsopgang: dagInfo.zonsopgang[index] != null ? dagInfo.zonsopgang[index] : null,
    zonsondergang: dagInfo.zonsondergang[index] != null ? dagInfo.zonsondergang[index] : null,
  };
}

// Pure logica: toetst de expliciete meldingsregel (minimale windkracht + windrichting-bereik)
// rechtstreeks tegen de voorspelde wind — los van de samengestelde score/kleur. Zie Meldingen.gs.


function voldoetAanMeldingDrempel(uurData, meldingDrempel) {
  if (!uurData || uurData.windKnopen == null || uurData.windrichtingGraden == null) return false;
  if (uurData.windKnopen < meldingDrempel.minimumWindKnopen) return false;
  return inGradenBereik(uurData.windrichtingGraden, meldingDrempel.richtingVan, meldingDrempel.richtingTot);
}

/** @returns {{tijdstip: string, uurData: Object}|null} het eerste uur (van bv. één dag) dat voldoet. */
function vindEersteMatchendUur(urenData, meldingDrempel) {
  return (urenData || []).filter((u) => voldoetAanMeldingDrempel(u.uurData, meldingDrempel))[0] || null;
}

// Pure logica: validatie, defaults-aanvulling en CRUD-helpers voor het gebruikersprofiel-JSON
// dat per unieke gebruikers-ID in Drive wordt opgeslagen. De gebruiker wordt geïdentificeerd via
// een niet-geraden ID in de URL (zie README.md "Aannames") i.p.v. een account/login.


// ZZW (202.5°) t/m NW (315°): de standaard meldingsregel, zoals opgegeven voor Rockanje/Maasvlakte.
const ZZW_GRADEN = 202.5;
const NW_GRADEN = 315;

function isEindigGetal(x) {
  return typeof x === 'number' && Number.isFinite(x);
}

/** Windrichting zit per favoriete locatie (kustoriëntatie is locatie-specifiek), niet globaal. */
function standaardDrempelwaardenZonderWindrichting() {
  const { windrichting, ...rest } = standaardDrempelwaarden();
  return rest;
}

/** De twee standaard-favorieten, met exacte coördinaten van kitesurfvereniging.nl se spotkaart. */
function standaardFavorieteLocaties() {
  const windrichting = { besteRanges: [[ZZW_GRADEN, NW_GRADEN]], acceptabeleRanges: [] };
  return [
    {
      id: 'rockanje-sportstrand',
      naam: 'Rockanje Sportstrand',
      lat: 51.8722925148425,
      lon: 4.044898266162127,
      windrichting,
    },
    {
      id: 'maasvlakte-2-slufter',
      naam: 'Maasvlakte 2 - Slufter',
      lat: 51.919079,
      lon: 3.988189,
      windrichting,
    },
  ];
}

function standaardDatabronnen() {
  return { openMeteo: true, buienradar: true, weerlive: true, rws: true, windfinder: true };
}

function standaardProfiel(gebruikerId) {
  return {
    gebruikerId: gebruikerId != null ? gebruikerId : null,
    email: null,
    // Gekoppeld door TelegramBot.gs zodra de gebruiker de bot start — niet handmatig instelbaar
    // in de UI (er is geen "vul je Telegram-ID in"-veld, dat zou te makkelijk te vervalsen zijn).
    telegramChatId: null,
    drempelwaarden: standaardDrempelwaardenZonderWindrichting(),
    databronnen: standaardDatabronnen(),
    // Aparte, expliciete meldingsregel (naast de algemene score/kleur-instellingen hierboven):
    // meldt wanneer de voorspelling minimaal deze windkracht EN een richting binnen dit bereik heeft.
    meldingDrempel: { minimumWindKnopen: 19, richtingVan: ZZW_GRADEN, richtingTot: NW_GRADEN },
    // I.t.t. de drempelwaarden hierboven heeft dit wél een concrete default: 09:00-20:00, gelijk
    // aan het vaste weergavevenster van de grafiek (zie GRAFIEK_START_UUR/EIND_UUR in
    // JavaScript.html) — zo is het dagoordeel altijd gebaseerd op hetzelfde venster als wat je
    // in de grafiek ziet.
    dagvenster: { startUur: 9, eindUur: 20 },
    favorieteLocaties: standaardFavorieteLocaties(),
    meldingen: { ingeschakeld: true, laatstGemeld: {} },
  };
}

/** Diepe merge van gebruikersinstellingen over de defaults heen, zonder onbekende velden over te nemen. */
function vulAanMetDefaults(waarden, defaults) {
  if (typeof defaults !== 'object' || defaults === null || Array.isArray(defaults)) {
    return waarden != null ? waarden : defaults;
  }
  const resultaat = {};
  Object.keys(defaults).forEach((key) => {
    const heeftWaarde = waarden && typeof waarden === 'object' && waarden[key] !== undefined;
    resultaat[key] = heeftWaarde ? vulAanMetDefaults(waarden[key], defaults[key]) : defaults[key];
  });
  return resultaat;
}

function valideerLocatie(ruweLocatie) {
  const fouten = [];
  const naam = typeof ruweLocatie?.naam === 'string' && ruweLocatie.naam.trim()
    ? ruweLocatie.naam.trim().slice(0, 100)
    : null;
  if (!naam) fouten.push('Locatienaam ontbreekt of is leeg');

  const lat = Number(ruweLocatie?.lat);
  const lon = Number(ruweLocatie?.lon);
  if (!isEindigGetal(lat) || lat < -90 || lat > 90) fouten.push('Ongeldige breedtegraad (lat)');
  if (!isEindigGetal(lon) || lon < -180 || lon > 180) fouten.push('Ongeldige lengtegraad (lon)');

  const besteRanges = Array.isArray(ruweLocatie?.windrichting?.besteRanges)
    ? ruweLocatie.windrichting.besteRanges.filter(
        (r) => Array.isArray(r) && r.length === 2 && isEindigGetal(r[0]) && isEindigGetal(r[1])
      )
    : [];
  const acceptabeleRanges = Array.isArray(ruweLocatie?.windrichting?.acceptabeleRanges)
    ? ruweLocatie.windrichting.acceptabeleRanges.filter(
        (r) => Array.isArray(r) && r.length === 2 && isEindigGetal(r[0]) && isEindigGetal(r[1])
      )
    : [];

  if (fouten.length > 0) return { locatie: null, fouten };

  const id = ruweLocatie.id || `${lat.toFixed(4)},${lon.toFixed(4)}`;
  return {
    locatie: { id, naam, lat, lon, windrichting: { besteRanges, acceptabeleRanges } },
    fouten: [],
  };
}

function valideerDagvenster(ruwDagvenster, defaultDagvenster) {
  const merged = vulAanMetDefaults(ruwDagvenster, defaultDagvenster);
  const clamp = (u) => Math.min(23, Math.max(0, Math.round(Number(u))));
  return {
    startUur: isEindigGetal(Number(merged.startUur)) ? clamp(merged.startUur) : defaultDagvenster.startUur,
    eindUur: isEindigGetal(Number(merged.eindUur)) ? clamp(merged.eindUur) : defaultDagvenster.eindUur,
  };
}

function valideerEmail(ruwEmail) {
  if (ruwEmail == null || ruwEmail === '') return null;
  const email = String(ruwEmail).trim().slice(0, 200);
  // Lichte validatie: geen volwaardige RFC-check nodig, MailApp.sendEmail geeft zelf een fout
  // terug bij een echt ongeldig adres. Dit voorkomt alleen overduidelijke onzin.
  return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email) ? email : null;
}

/**
 * Valideert een ruw (bv. uit Drive of van de client) profiel-object en vult ontbrekende
 * velden aan met defaults. Onherstelbaar ongeldige favoriete locaties worden overgeslagen
 * (met een foutmelding) i.p.v. het hele profiel af te wijzen.
 */
function valideerEnVulProfielAan(ruwProfiel, gebruikerId) {
  const fouten = [];
  const basis = standaardProfiel(gebruikerId);

  if (ruwProfiel != null && typeof ruwProfiel !== 'object') {
    return { profiel: basis, fouten: ['Profiel was geen object, standaardprofiel gebruikt'] };
  }

  const drempelwaarden = vulAanMetDefaults(ruwProfiel?.drempelwaarden, basis.drempelwaarden);
  const databronnen = vulAanMetDefaults(ruwProfiel?.databronnen, basis.databronnen);
  const meldingDrempel = vulAanMetDefaults(ruwProfiel?.meldingDrempel, basis.meldingDrempel);
  const dagvenster = valideerDagvenster(ruwProfiel?.dagvenster, basis.dagvenster);
  const telegramChatId = ruwProfiel?.telegramChatId != null ? ruwProfiel.telegramChatId : null;

  // Favoriete locaties: alleen aanvullen met de standaard-favorieten als het veld helemaal
  // ontbreekt (nieuw profiel) — een gebruiker die ze bewust verwijderd heeft, moet dat zo houden.
  const favorieteLocatiesRuw = Array.isArray(ruwProfiel?.favorieteLocaties)
    ? ruwProfiel.favorieteLocaties
    : ruwProfiel == null
      ? basis.favorieteLocaties
      : [];

  const favorieteLocaties = [];
  favorieteLocatiesRuw.forEach((ruw) => {
    const { locatie, fouten: locatieFouten } = valideerLocatie(ruw);
    if (locatie) favorieteLocaties.push(locatie);
    else fouten.push(...locatieFouten.map((f) => `Locatie "${ruw?.naam || '?'}": ${f}`));
  });

  const meldingen = {
    ingeschakeld: ruwProfiel?.meldingen?.ingeschakeld !== false,
    laatstGemeld:
      ruwProfiel?.meldingen?.laatstGemeld && typeof ruwProfiel.meldingen.laatstGemeld === 'object'
        ? ruwProfiel.meldingen.laatstGemeld
        : {},
  };

  return {
    profiel: {
      gebruikerId: gebruikerId != null ? gebruikerId : ruwProfiel?.gebruikerId || null,
      email: valideerEmail(ruwProfiel?.email),
      telegramChatId,
      drempelwaarden,
      databronnen,
      meldingDrempel,
      dagvenster,
      favorieteLocaties,
      meldingen,
    },
    fouten,
  };
}

function voegFavorieteLocatieToe(profiel, ruweLocatie) {
  const { locatie, fouten } = valideerLocatie(ruweLocatie);
  if (!locatie) return { profiel, fouten };
  const bestaatAl = profiel.favorieteLocaties.some((l) => l.id === locatie.id);
  if (bestaatAl) return { profiel, fouten: ['Locatie staat al in favorieten'] };
  return {
    profiel: { ...profiel, favorieteLocaties: [...profiel.favorieteLocaties, locatie] },
    fouten: [],
  };
}

function verwijderFavorieteLocatie(profiel, locatieId) {
  return {
    ...profiel,
    favorieteLocaties: profiel.favorieteLocaties.filter((l) => l.id !== locatieId),
  };
}

// Pure logica: parseert de Rijkswaterstaat WaterWebservices-respons (getij/waterstand) en
// classificeert per uur of het "hoog" of "laag" water is. RWS levert geen kant-en-klare
// hoog/laag-classificatie, dus die wordt hier afgeleid uit de min/max van de opgehaalde reeks.
// Zie databronnen-kiteweer-app.md en README.md "Aannames" voor de stationskeuze (Hoek van Holland
// dekt zowel Rockanje als Maasvlakte, de twee standaard-favorieten).

/**
 * Parseert de respons van POST .../ONLINEWAARNEMINGENSERVICES/OphalenWaarnemingen.
 * Kiest bij voorkeur ProcesType "verwachting" (met weersinvloed, beste match voor een
 * weersverwachting), valt terug op "astronomisch" als die ontbreekt.
 * @returns {{tijdstippen: string[], waterstandCm: number[]}}
 */
function parseRwsGetij(json) {
  var lijst = (json && json.WaarnemingenLijst) || [];
  var gekozen =
    lijst.filter(function (w) { return w.AquoMetadata && w.AquoMetadata.ProcesType === 'verwachting'; })[0] ||
    lijst.filter(function (w) { return w.AquoMetadata && w.AquoMetadata.ProcesType === 'astronomisch'; })[0];

  if (!gekozen) return { tijdstippen: [], waterstandCm: [] };

  var metingen = gekozen.MetingenLijst || [];
  return {
    tijdstippen: metingen.map(function (m) { return m.Tijdstip; }),
    waterstandCm: metingen.map(function (m) {
      return m.Meetwaarde ? m.Meetwaarde.Waarde_Numeriek : null;
    }),
  };
}

/**
 * Classificeert elk punt als 'hoog' of 'laag' t.o.v. het midden van de min/max-range van de
 * gegeven reeks. Eenvoudige, robuuste heuristiek — geen echte piek/dal-detectie nodig omdat
 * evalueerGetij() alleen een grove hoog/laag-voorkeur toetst, geen exact getij-tijdstip.
 * @param {number[]} waterstandCm
 * @returns {Array<'hoog'|'laag'|null>}
 */
function classificeerGetijStatus(waterstandCm) {
  var geldig = (waterstandCm || []).filter(function (w) { return w != null; });
  if (geldig.length === 0) return (waterstandCm || []).map(function () { return null; });

  var min = Math.min.apply(null, geldig);
  var max = Math.max.apply(null, geldig);
  var midden = (min + max) / 2;

  return (waterstandCm || []).map(function (w) {
    if (w == null) return null;
    return w >= midden ? 'hoog' : 'laag';
  });
}

// Pure logica: combineert de drempelwaarde-evaluaties tot een score (1-10) en kleurcode
// per uur en per dag, volgens het "Voorstel scoreberekening" in criteria-kiteweer-app.md.


// Hoofdcriteria (windsnelheid, windrichting, windvlagen, getij) bepalen samen 85% van de score;
// het facultatieve restje (lucht-/watertemperatuur, golfhoogte, zicht) 15%. "Weer" (onweer/buien)
// zit hier bewust niet als percentage bij — dat werkt al als hard-gate (harde no-go bij onweer)
// plus een vermenigvuldigende straf bij een neerslagwaarschuwing, dus met nóg meer gewicht dan
// een gewoon percentage zou geven. "Actuele wind" is geen aparte categorie: die wordt via
// bronnenMiddeling al rechtstreeks in windsnelheid/windrichting meegewogen op het "nu"-uur
// (zie forecastSamenstellen.js) — dezelfde hoofdcriteria, alleen met een actuele meting erbij.
const GEWICHTEN = {
  windsnelheid: 0.35,
  windrichting: 0.2,
  windvlagen: 0.15,
  getij: 0.15,
  facultatief: 0.15,
};

function scoreNaarKleur(score) {
  if (score >= 8) return 'groen';
  if (score >= 5) return 'oranje';
  return 'rood';
}

/**
 * Berekent de score/kleur voor één uur op basis van alle (gemiddelde) meetwaarden op dat uur.
 * @param {Object} uurData - windKnopen, windvlaagKnopen, windrichtingGraden, onweerAanwezig,
 *   neerslagKans, luchttemperatuurCelsius, watertemperatuurCelsius, golfhoogteMeter,
 *   getijStatus, zichtKm (elk optioneel/null als de bron niet beschikbaar is).
 * @param {Object} instellingen - per-variabele drempelwaarden (zie standaardDrempelwaarden()).
 */
function berekenUurScore(uurData, instellingen) {
  const i = { ...standaardDrempelwaarden(), ...(instellingen || {}) };
  const d = uurData || {};

  const evaluaties = {
    windsnelheid: evalueerWindsnelheid(d.windKnopen, i.windsnelheid),
    windrichting: evalueerWindrichting(d.windrichtingGraden, i.windrichting),
    windvlagen: evalueerWindvlagen(d.windKnopen, d.windvlaagKnopen, i.windvlagen),
    onweer: evalueerOnweer(d.onweerAanwezig, d.neerslagKans, i.onweer),
    luchttemperatuur: evalueerLuchttemperatuur(d.luchttemperatuurCelsius, i.luchttemperatuur),
    watertemperatuur: evalueerWatertemperatuur(d.watertemperatuurCelsius, i.watertemperatuur),
    golfhoogte: evalueerGolfhoogte(d.golfhoogteMeter, i.golfhoogte),
    getij: evalueerGetij(d.getijStatus, i.getij),
    zicht: evalueerZicht(d.zichtKm, i.zicht),
  };

  const noGoRedenen = Object.entries(evaluaties)
    .filter(([, e]) => e.noGo)
    .map(([variabele, e]) => ({ variabele, reden: e.reden }));

  if (noGoRedenen.length > 0) {
    return { score: 0, kleur: 'rood', noGo: true, redenen: noGoRedenen, evaluaties };
  }

  const facultatieveScores = [
    evaluaties.luchttemperatuur.score,
    evaluaties.watertemperatuur.score,
    evaluaties.golfhoogte.score,
    evaluaties.zicht.score,
  ];
  const facultatiefGemiddelde = facultatieveScores.reduce((s, v) => s + v, 0) / facultatieveScores.length;

  // evalueerOnweer geeft bij een waarschuwing (hoge neerslagkans) 0.5 i.p.v. een no-go;
  // die waarschuwing weegt mee via een vermenigvuldigende straf op de hele score (zie GEWICHTEN).
  const onweerWaarschuwingFactor = evaluaties.onweer.score;

  const gewogen =
    evaluaties.windsnelheid.score * GEWICHTEN.windsnelheid +
    evaluaties.windrichting.score * GEWICHTEN.windrichting +
    evaluaties.windvlagen.score * GEWICHTEN.windvlagen +
    evaluaties.getij.score * GEWICHTEN.getij +
    facultatiefGemiddelde * GEWICHTEN.facultatief;

  const score = Number((gewogen * onweerWaarschuwingFactor * 10).toFixed(1));
  return { score, kleur: scoreNaarKleur(score), noGo: false, redenen: [], evaluaties };
}

/**
 * Aggregeert de uurscores van één dag tot één dagoordeel: het beste (niet-no-go) moment
 * binnen het daglichtvenster bepaalt de dagkleur/score ("is er vandaag een goed moment").
 * @param {Array<{tijdstip: string, uurData: Object}>} urenVanDag
 * @param {Object} instellingen
 * @param {{dagvensterStartUur?: number, dagvensterEindUur?: number}} [opties]
 */
function berekenDagScore(urenVanDag, instellingen, opties) {
  const startUur = (opties && opties.dagvensterStartUur) != null ? opties.dagvensterStartUur : 6;
  const eindUur = (opties && opties.dagvensterEindUur) != null ? opties.dagvensterEindUur : 21;

  const uurResultaten = (urenVanDag || []).map((u) => ({
    tijdstip: u.tijdstip,
    ...berekenUurScore(u.uurData, instellingen),
    // Rauwe meetwaarden (naast de afgeleide status/score in `evaluaties`) — voor een directe
    // visuele weergave (pijl + kn) in de UI, los van de go/no-go-interpretatie.
    ruw: {
      windKnopen: u.uurData ? u.uurData.windKnopen : null,
      windvlaagKnopen: u.uurData ? u.uurData.windvlaagKnopen : null,
      windrichtingGraden: u.uurData ? u.uurData.windrichtingGraden : null,
    },
  }));

  const binnenVenster = uurResultaten.filter((u) => {
    const uur = new Date(u.tijdstip).getHours();
    return uur >= startUur && uur <= eindUur;
  });
  const relevant = binnenVenster.length > 0 ? binnenVenster : uurResultaten;

  if (relevant.length === 0) {
    return { score: 0, kleur: 'rood', noGo: true, besteUur: null, uurResultaten };
  }

  const besteUur = relevant.reduce((beste, u) => (u.score > beste.score ? u : beste), relevant[0]);

  return {
    score: besteUur.score,
    kleur: besteUur.kleur,
    noGo: besteUur.noGo,
    besteUur,
    uurResultaten,
  };
}

// GAS-specifiek: verstuurt meldingen (e-mail via het ingebouwde MailApp, en/of een Telegram-
// bericht als de gebruiker de bot gestart heeft — zie TelegramBot.gs) en bevat de time-driven
// trigger die per gebruiker controleert of de eigen expliciete meldingsregel gehaald wordt (zie
// src/logica/meldingLogica.js): minimale windkracht (knopen) EN windrichting binnen een bereik
// (standaard: minimaal 19 knopen, richting tussen ZZW en NW), binnen het ingestelde dagvenster
// (standaard 09:00-20:00, gelijk aan het weergavevenster van de grafiek).

/**
 * Aan te roepen via een time-driven trigger (zie SETUP.md, bv. elk uur). Meldt hooguit één keer
 * per dag per favoriete locatie (via meldingen.laatstGemeld) om spam te voorkomen.
 */
function controleerDrempelwaardenEnMeld() {
  var profielen = laadAlleProfielen_();
  var vandaag = Utilities.formatDate(new Date(), 'Europe/Amsterdam', 'yyyy-MM-dd');

  profielen.forEach(function (profiel) {
    var heeftKanaal = !!profiel.email || !!profiel.telegramChatId;
    if (!profiel.meldingen.ingeschakeld || !heeftKanaal) return;

    profiel.favorieteLocaties.forEach(function (locatie) {
      if (profiel.meldingen.laatstGemeld[locatie.id] === vandaag) return;

      var urenData = haalWeerDataOp_(locatie.lat, locatie.lon, profiel.databronnen).urenData;
      var urenVandaagBinnenVenster = urenData.filter(function (uur) {
        var isVandaag = Utilities.formatDate(new Date(uur.tijdstip), 'Europe/Amsterdam', 'yyyy-MM-dd') === vandaag;
        var uurVanDag = Number(Utilities.formatDate(new Date(uur.tijdstip), 'Europe/Amsterdam', 'H'));
        var binnenVenster = uurVanDag >= profiel.dagvenster.startUur && uurVanDag <= profiel.dagvenster.eindUur;
        return isVandaag && binnenVenster;
      });
      var matchendUur = vindEersteMatchendUur(urenVandaagBinnenVenster, profiel.meldingDrempel);

      if (matchendUur) {
        if (profiel.email) verstuurMeldingEmail_(profiel.email, locatie, matchendUur, profiel.meldingDrempel);
        if (profiel.telegramChatId) verstuurMeldingTelegram_(profiel.telegramChatId, locatie, matchendUur, profiel.meldingDrempel);
        profiel.meldingen.laatstGemeld[locatie.id] = vandaag;
        slaProfielOp_(profiel.gebruikerId, profiel);
      }
    });
  });
}

function formatMeldingTekst_(locatie, matchendUur, meldingDrempel) {
  var tijd = Utilities.formatDate(new Date(matchendUur.tijdstip), 'Europe/Amsterdam', 'HH:mm');
  return (
    'Vandaag rond ' + tijd + ' bij ' + locatie.naam + ': ' +
    matchendUur.uurData.windKnopen.toFixed(1) + ' knopen uit ' +
    Math.round(matchendUur.uurData.windrichtingGraden) + '°.\n\n' +
    'Dit voldoet aan je meldingsregel (minimaal ' + meldingDrempel.minimumWindKnopen +
    ' knopen, richting tussen ' + meldingDrempel.richtingVan + '° en ' + meldingDrempel.richtingTot + '°).'
  );
}

function verstuurMeldingEmail_(email, locatie, matchendUur, meldingDrempel) {
  var onderwerp = '🪁 Kitesurf-mogelijkheid bij ' + locatie.naam;
  MailApp.sendEmail(email, onderwerp, formatMeldingTekst_(locatie, matchendUur, meldingDrempel));
}

function verstuurMeldingTelegram_(chatId, locatie, matchendUur, meldingDrempel) {
  var webappUrl = ScriptApp.getService().getUrl();
  var tekst =
    '🪁 Kitesurf-mogelijkheid bij ' + locatie.naam + '!\n\n' +
    formatMeldingTekst_(locatie, matchendUur, meldingDrempel) +
    '\n\nBekijk de app: ' + webappUrl;
  verstuurTelegramBotBericht_(chatId, tekst);
}

// GAS-specifiek: leest/schrijft het gebruikersprofiel-JSON in Drive, gekoppeld aan het unieke
// gebruikers-ID (zie Code.gs). Bestanden staan in een niet-publiek gedeelde map (zie Config.gs:
// getProfielenMapId_) en worden uitsluitend door de backend gelezen/geschreven.

function profielBestandsnaam_(gebruikerId) {
  return 'profiel-' + gebruikerId + '.json';
}

function vindProfielBestand_(map, gebruikerId) {
  var bestanden = map.getFilesByName(profielBestandsnaam_(gebruikerId));
  return bestanden.hasNext() ? bestanden.next() : null;
}

/** Laadt en valideert het profiel van een gebruiker; bestaat het nog niet, dan het standaardprofiel. */
function laadProfiel_(gebruikerId) {
  var map = DriveApp.getFolderById(getProfielenMapId_());
  var bestand = vindProfielBestand_(map, gebruikerId);
  var ruw = bestand ? JSON.parse(bestand.getBlob().getDataAsString()) : null;
  var resultaat = valideerEnVulProfielAan(ruw, gebruikerId);
  return resultaat.profiel;
}

/** Valideert en slaat het profiel op (maakt het bestand aan als het nog niet bestaat). */
function slaProfielOp_(gebruikerId, ruwProfiel) {
  var resultaat = valideerEnVulProfielAan(ruwProfiel, gebruikerId);
  var map = DriveApp.getFolderById(getProfielenMapId_());
  var bestand = vindProfielBestand_(map, gebruikerId);
  var inhoud = JSON.stringify(resultaat.profiel);
  if (bestand) {
    bestand.setContent(inhoud);
  } else {
    map.createFile(profielBestandsnaam_(gebruikerId), inhoud, MimeType.PLAIN_TEXT);
  }
  return resultaat;
}

/** Alle opgeslagen profielen (gebruikt door de meldingen-trigger, zie Meldingen.gs). */
function laadAlleProfielen_() {
  var map = DriveApp.getFolderById(getProfielenMapId_());
  var bestanden = map.getFiles();
  var profielen = [];
  while (bestanden.hasNext()) {
    var bestand = bestanden.next();
    try {
      var ruw = JSON.parse(bestand.getBlob().getDataAsString());
      profielen.push(valideerEnVulProfielAan(ruw, ruw && ruw.gebruikerId).profiel);
    } catch (e) {
      // Eén corrupt profiel-bestand mag de trigger voor alle andere gebruikers niet blokkeren.
    }
  }
  return profielen;
}

// GAS-specifiek: eenmalige installatiefunctie. Handmatig één keer uitvoeren vanuit de Apps
// Script-editor (Run -> installeerMeldingenTrigger) na het invullen van de Script Properties,
// zie SETUP.md. Triggers kunnen niet via `clasp push` worden aangemaakt.

function installeerMeldingenTrigger() {
  // Voorkom dubbele triggers als deze functie per ongeluk twee keer wordt gedraaid.
  ScriptApp.getProjectTriggers()
    .filter(function (t) {
      return t.getHandlerFunction() === 'controleerDrempelwaardenEnMeld';
    })
    .forEach(function (t) {
      ScriptApp.deleteTrigger(t);
    });

  ScriptApp.newTrigger('controleerDrempelwaardenEnMeld').timeBased().everyHours(1).create();
}

// GAS-specifiek: een lichte, aparte koppeling met de eerder aangemaakte Telegram-bot
// (@ShouldIKite_bot / "Kiting9to5") — NIET als Mini App (zie README.md "Aannames" #1 voor
// waarom dat structureel niet werkt met Apps Script), maar als tweerichtings-kanaal:
// - Wie de bot start, krijgt de webapp-link terug (gekoppeld aan een eigen profiel).
// - Zodra de meldingsregel gehaald wordt (zie Meldingen.gs), stuurt de bot een kitesurf-alert.
//
// Vereist eenmalig (zie SETUP.md): TELEGRAM_BOT_TOKEN in Script Properties, en daarna
// `registreerTelegramWebhook()` één keer handmatig draaien vanuit de Apps Script-editor.

/** Zoekt of er al een profiel bestaat voor dit Telegram-chat-ID (lineaire scan; verwacht kleine gebruikersaantallen). */
function vindGebruikerIdVoorTelegramChatId_(chatId) {
  var profielen = laadAlleProfielen_();
  for (var i = 0; i < profielen.length; i++) {
    if (profielen[i].telegramChatId === chatId) return profielen[i].gebruikerId;
  }
  return null;
}

/**
 * Verwerkt een inkomend Telegram-bericht (elk bericht, niet alleen /start): koppelt (of
 * hergebruikt) een profiel aan dit chat-ID en stuurt de persoonlijke app-link terug.
 * Let op: dit is een apart profiel van een eventueel al bestaand browser-profiel van dezelfde
 * persoon — er is geen manier om ze aan elkaar te koppelen (zie README.md "Aannames").
 */
function verwerkTelegramBericht_(message) {
  var chatId = message && message.chat && message.chat.id;
  if (!chatId) return;

  var gebruikerId = vindGebruikerIdVoorTelegramChatId_(chatId);
  var nieuw = !gebruikerId;
  if (nieuw) {
    gebruikerId = Utilities.getUuid();
    var profiel = laadProfiel_(gebruikerId);
    profiel.telegramChatId = chatId;
    slaProfielOp_(gebruikerId, profiel);
  }

  var appLink = ScriptApp.getService().getUrl() + '?id=' + encodeURIComponent(gebruikerId);
  var tekst = nieuw
    ? '🪁 Welkom bij de Kite Weer App!\n\n' +
      'Open de app hier om je e-mailadres, criteria en dagvenster in te stellen:\n' + appLink + '\n\n' +
      'Zodra de voorspelling bij een favoriete locatie aan je meldingsregel voldoet (minimaal ' +
      'de ingestelde windkracht + richting), stuur ik hier een kitesurf-alert.\n\n' +
      'Bewaar de link hierboven — er is geen account/login.'
    : '🪁 Je hebt al een profiel gekoppeld. Open de app hier:\n' + appLink;
  verstuurTelegramBotBericht_(chatId, tekst);
}

function verstuurTelegramBotBericht_(chatId, tekst) {
  var token = getBotToken_();
  if (!token) return; // Geen token ingesteld: bot-koppeling staat uit, geen foutmelding nodig.
  UrlFetchApp.fetch('https://api.telegram.org/bot' + token + '/sendMessage', {
    method: 'post',
    contentType: 'application/json',
    muteHttpExceptions: true,
    payload: JSON.stringify({ chat_id: chatId, text: tekst }),
  });
}

/**
 * Eenmalig handmatig te draaien (Apps Script-editor -> functie selecteren -> Run), ná het
 * invullen van TELEGRAM_BOT_TOKEN. Vertelt Telegram om berichten aan de bot naar deze webapp
 * door te sturen (doPost in Code.gs), zodat verwerkTelegramBericht_ ze kan afhandelen.
 */
function registreerTelegramWebhook() {
  var token = getBotToken_();
  if (!token) {
    Logger.log('Geen TELEGRAM_BOT_TOKEN ingesteld in Script Properties — zie SETUP.md.');
    return;
  }
  var webappUrl = ScriptApp.getService().getUrl();
  var response = UrlFetchApp.fetch(
    'https://api.telegram.org/bot' + token + '/setWebhook?url=' + encodeURIComponent(webappUrl),
    { muteHttpExceptions: true }
  );
  Logger.log(response.getContentText());
}

// GAS-specifiek: haalt de rauwe databronnen op (UrlFetchApp) met caching (CacheService),
// en roept de pure parsers/samensteller (src/logica/) aan om er uurData van te maken.
// Zie databronnen-kiteweer-app.md voor de bronnen en caching-motivatie (gratis-quota's sparen).
//
// Efficiëntie: tot 8 bronnen per locatie is veel om ná elkaar op te halen (som van alle
// latenties). haalWeerDataOp_ verzamelt daarom eerst alle cache-missers en haalt die in één
// keer parallel op via UrlFetchApp.fetchAll() — de totale wachttijd wordt zo de LANGZAAMSTE
// enkele bron i.p.v. de SOM van alle bronnen.

var WEER_CACHE_SECONDEN = 600; // 10 minuten, zoals aanbevolen in databronnen-kiteweer-app.md

function cacheSleutel_(prefix, lat, lon) {
  return prefix + '_' + lat.toFixed(2) + '_' + lon.toFixed(2);
}

/** Nederland bij benadering (bounding box), voor de NL-only bronnen Buienradar/Weerlive/RWS. */
function isInNederland_(lat, lon) {
  return lat >= 50.5 && lat <= 53.7 && lon >= 3.2 && lon <= 7.3;
}

/**
 * Voert een lijst databron-"taken" uit: cache-hits direct teruggeven, cache-missers in één
 * parallelle batch ophalen (UrlFetchApp.fetchAll), daarna elk resultaat verwerken en cachen.
 * @param {Array<{sleutel: string, cacheKey: string, request: Object, verwerk?: (tekst:string)=>*}>} taken
 * @returns {Object} sleutel -> verwerkte waarde (of null bij fout/ontbrekend)
 */
function voerBatchOp_(taken) {
  var cache = CacheService.getScriptCache();
  var resultaten = {};
  var teFetchen = [];

  taken.forEach(function (taak) {
    var cached = cache.get(taak.cacheKey);
    if (cached) {
      try {
        resultaten[taak.sleutel] = JSON.parse(cached);
        return;
      } catch (e) {
        // corrupte cache-waarde: gewoon opnieuw ophalen.
      }
    }
    teFetchen.push(taak);
  });

  if (teFetchen.length > 0) {
    var responses;
    try {
      responses = UrlFetchApp.fetchAll(teFetchen.map(function (t) { return t.request; }));
    } catch (e) {
      responses = teFetchen.map(function () { return null; });
    }
    teFetchen.forEach(function (taak, i) {
      var response = responses[i];
      var waarde = null;
      try {
        if (response && response.getResponseCode() === 200) {
          var verwerk = taak.verwerk || JSON.parse;
          waarde = verwerk(response.getContentText());
        }
      } catch (e) {
        waarde = null; // Onverwachte respons-vorm: bron overslaan i.p.v. de hele batch te breken.
      }
      resultaten[taak.sleutel] = waarde;
      if (waarde != null) {
        try {
          cache.put(taak.cacheKey, JSON.stringify(waarde), WEER_CACHE_SECONDEN);
        } catch (e) {
          // Waarde te groot (>100KB) of andere cache-fout: caching is best-effort.
        }
      }
    });
  }

  return resultaten;
}

function openMeteoForecastTaak_(lat, lon) {
  var url =
    'https://api.open-meteo.com/v1/forecast?latitude=' + lat + '&longitude=' + lon +
    '&hourly=wind_speed_10m,wind_direction_10m,wind_gusts_10m,weather_code,precipitation_probability,temperature_2m,visibility,cloud_cover' +
    '&daily=sunrise,sunset' +
    '&wind_speed_unit=kn&forecast_days=3&timezone=auto';
  return { sleutel: 'openMeteo', cacheKey: cacheSleutel_('om_forecast', lat, lon), request: { url: url, muteHttpExceptions: true } };
}

function openMeteoMarineTaak_(lat, lon) {
  var url =
    'https://marine-api.open-meteo.com/v1/marine?latitude=' + lat + '&longitude=' + lon +
    '&hourly=wave_height,wave_direction,wave_period,sea_surface_temperature&forecast_days=3&timezone=auto';
  return { sleutel: 'openMeteoMarine', cacheKey: cacheSleutel_('om_marine', lat, lon), request: { url: url, muteHttpExceptions: true } };
}

function buienradarTaak_() {
  return {
    sleutel: 'buienradar',
    cacheKey: 'buienradar_feed',
    request: { url: 'https://data.buienradar.nl/2.0/feed/json', muteHttpExceptions: true },
  };
}

function weerliveTaak_(lat, lon, apiKey) {
  var url = 'https://weerlive.nl/api/json-data-10min.php?key=' + encodeURIComponent(apiKey) + '&locatie=' + lat + ',' + lon;
  return { sleutel: 'weerlive', cacheKey: cacheSleutel_('weerlive', lat, lon), request: { url: url, muteHttpExceptions: true } };
}

/**
 * RWS meet op "hoekvanholland" naast getij ook wind (WINDSHD/WINDRTG) — alle favorieten uit deze
 * app liggen in de Voordelta/Nieuwe Waterweg-monding, waarvoor dit het dichtstbijzijnde officiële
 * meetpunt is (zie README.md "Aannames" — geen generieke dichtstbijzijnde-meetpunt-lookup,
 * bewust beperkt tot deze regio). Er bestaat ook een meetpunt vlak bij Rockanje zelf
 * ("rockanje.2eslag", incl. wind), maar die gaf tijdens de bouw geen actuele data terug
 * (HTTP 204) — waarschijnlijk (tijdelijk) buiten gebruik.
 */
var RWS_LOCATIE_CODE = 'hoekvanholland';

function rwsWaarnemingenTaak_(sleutel, grootheidCode, compartimentCode) {
  var nu = new Date();
  var eind = new Date(nu.getTime() + 3 * 24 * 60 * 60 * 1000);
  var aquoMetadata = { Grootheid: { Code: grootheidCode } };
  if (compartimentCode) aquoMetadata.Compartiment = { Code: compartimentCode };
  var body = {
    Locatie: { Code: RWS_LOCATIE_CODE },
    AquoPlusWaarnemingMetadata: { AquoMetadata: aquoMetadata },
    Periode: {
      Begindatumtijd: Utilities.formatDate(nu, 'Europe/Amsterdam', "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"),
      Einddatumtijd: Utilities.formatDate(eind, 'Europe/Amsterdam', "yyyy-MM-dd'T'HH:mm:ss.SSSXXX"),
    },
  };
  return {
    sleutel: sleutel,
    cacheKey: 'rws_' + grootheidCode + '_' + RWS_LOCATIE_CODE,
    request: {
      url: 'https://ddapi20-waterwebservices.rijkswaterstaat.nl/ONLINEWAARNEMINGENSERVICES/OphalenWaarnemingen',
      method: 'post',
      contentType: 'application/json',
      payload: JSON.stringify(body),
      muteHttpExceptions: true,
    },
  };
}

/**
 * Windfinder.com — geen publieke API; de forecast-pagina bevat de volledige meerdaagse
 * voorspelling (wind, golven, getij) als ingebakken JSON (zie parseWindfinderForecast in
 * src/logica/bronParsers.js). Alleen bekende, met de hand gekoppelde spots (geen generieke
 * lat/lon-naar-Windfinder-spot-lookup) — zie README.md "Aannames".
 */
var WINDFINDER_SPOTS = [
  { naam: 'Rockanje', lat: 51.8722925148425, lon: 4.044898266162127, slug: 'rockanje' },
  { naam: 'Maasvlakte', lat: 51.919079, lon: 3.988189, slug: 'maasvlakte' },
];
var WINDFINDER_MAX_AFSTAND_KM = 5;

function vindWindfinderSlug_(lat, lon) {
  var dichtstbij = dichtstbijzijnde(lat, lon, WINDFINDER_SPOTS);
  if (!dichtstbij) return null;
  return afstandKm(lat, lon, dichtstbij.lat, dichtstbij.lon) <= WINDFINDER_MAX_AFSTAND_KM ? dichtstbij.slug : null;
}

/** Verwerkt (parseert) direct i.p.v. de rauwe ~280KB pagina te cachen — dat past niet binnen de 100KB-cachelimiet. */
function windfinderTaak_(slug) {
  return {
    sleutel: 'windfinder',
    cacheKey: 'windfinder_' + slug,
    request: {
      url: 'https://www.windfinder.com/forecast/' + slug,
      muteHttpExceptions: true,
      headers: { 'User-Agent': 'Mozilla/5.0 (compatible; KiteWeerApp/1.0)' },
    },
    verwerk: parseWindfinderForecast,
  };
}

/**
 * Haalt en combineert alle databronnen voor één locatie tot een uurData-array (per tijdstip),
 * klaar voor scoreBerekening.berekenDagScore. Ontbrekende/onbereikbare bronnen worden overgeslagen
 * (bronnenMiddeling.js negeert ontbrekende bronnen, telt ze niet als 0).
 * @param {Object} [databronnen] - welke bronnen te gebruiken (zie profielValidatie.standaardDatabronnen()
 *   voor de vorm); ontbrekende sleutels tellen als "aan".
 * @returns {{urenData: Array, zonInfo: {datums: string[], zonsopgang: string[], zonsondergang: string[]}}}
 */
function haalWeerDataOp_(lat, lon, databronnen) {
  var d = databronnen || {};
  var inNL = isInNederland_(lat, lon);
  var weerliveKey = getWeerliveApiKey_();
  var windfinderSlug = d.windfinder !== false ? vindWindfinderSlug_(lat, lon) : null;

  var taken = [];
  if (d.openMeteo !== false) {
    taken.push(openMeteoForecastTaak_(lat, lon));
    taken.push(openMeteoMarineTaak_(lat, lon));
  }
  if (inNL && d.buienradar !== false) taken.push(buienradarTaak_());
  if (inNL && d.weerlive !== false && weerliveKey) taken.push(weerliveTaak_(lat, lon, weerliveKey));
  if (inNL && d.rws !== false) {
    taken.push(rwsWaarnemingenTaak_('rwsGetij', 'WATHTE', 'OW'));
    taken.push(rwsWaarnemingenTaak_('rwsWindshd', 'WINDSHD'));
    taken.push(rwsWaarnemingenTaak_('rwsWindrtg', 'WINDRTG'));
  }
  if (windfinderSlug) taken.push(windfinderTaak_(windfinderSlug));

  var r = voerBatchOp_(taken);

  var openMeteo = parseOpenMeteoForecast(r.openMeteo || {});
  var openMeteoMarine = r.openMeteoMarine ? parseOpenMeteoMarine(r.openMeteoMarine) : null;
  var buienradar = r.buienradar ? parseBuienradarFeed(r.buienradar, lat, lon) : null;
  var weerlive = r.weerlive ? parseWeerlive(r.weerlive) : null;
  var rwsGetij = r.rwsGetij ? parseRwsGetij(r.rwsGetij) : null;
  var rwsWindVerwachting = r.rwsWindshd ? parseRwsWindVerwachting(r.rwsWindshd, r.rwsWindrtg || {}) : null;
  var rwsWindMeting = r.rwsWindshd ? parseRwsWindMeting(r.rwsWindshd, r.rwsWindrtg || {}) : null;
  // r.windfinder is door windfinderTaak_'s `verwerk` al het geparseerde object, geen JSON.parse meer nodig.
  var windfinder = r.windfinder || null;

  var urenData = samenstellenUrenData({
    openMeteo: openMeteo,
    openMeteoMarine: openMeteoMarine,
    buienradar: buienradar,
    weerlive: weerlive,
    windfinder: windfinder,
    rwsGetij: rwsGetij,
    rwsWindVerwachting: rwsWindVerwachting,
    rwsWindMeting: rwsWindMeting,
    huidigTijdstipIso: new Date().toISOString(),
  });

  return { urenData: urenData, zonInfo: openMeteo.dagInfo };
}
